function ledgerTeacherAssessment(subject){var t=teacherContacts[subject]||{},record=(schoolTeachers||[]).find(function(item){return String(item.name||'').trim()===String(t.name||'').trim()})||{},key=function(v){return String(v||'').toLowerCase().replace(/^(pak|bu|bapak|ibu)\s+/,'').replace(/[^a-z0-9]/g,'')},subjectKey=String(subject||'Mapel').replace(/[^a-z0-9_-]/gi,'_'),candidates=[key(t.call||record.call),key(t.name),key(record.name)],values={},semester=window.activeSemester||localStorage.getItem('aiwalas.semester')||'Ganjil';candidates=candidates.filter(function(v,i,a){return v&&a.indexOf(v)===i});function read(raw){try{values=JSON.parse(raw)||{};return Object.keys(values).length>0}catch(e){return false}}for(var c=0;c<candidates.length;c++){var keys=['aiwalas.assessment.v6.'+semester+'.'+candidates[c]+'.'+subjectKey,'aiwalas.assessment.v6.'+candidates[c]+'.'+subjectKey];for(var i=0;i<keys.length;i++){var raw=localStorage.getItem(keys[i]);if(raw&&read(raw))return values}}var suffix='.'+subjectKey;for(var n=0;n<localStorage.length;n++){var storageName=localStorage.key(n)||'';if(storageName.indexOf('aiwalas.assessment.v6.')===0&&storageName.slice(-suffix.length)===suffix){var fallback=localStorage.getItem(storageName);if(fallback&&read(fallback))return values}}return values}function ledgerReportValue(row){var parts=['UH1','UH2','UH3','UH4','UH5','UH6'],score=function(v){if(v==null||String(v).trim()==='')return null;var n=Number(String(v).replace(',','.').replace(/[^0-9.-]/g,''));return isNaN(n)?null:Math.max(0,Math.min(100,n))},uh=parts.map(function(c){return score(row[c])}).filter(function(v){return v!==null}),avg=uh.length?Math.round(uh.reduce(function(a,b){return a+b},0)/uh.length):null,ats=score(row.ATS),ass=score(row.ASS),available=uh.concat(ats===null?[]:[ats],ass===null?[]:[ass]);return available.length===1?available[0]:avg!==null&&ats!==null&&ass!==null?Math.round((3*avg+ats+2*ass)/6):avg!==null&&ats!==null?Math.round((3*avg+ats)/4):null}
